using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace Meilisearch
{
    /// <summary>
    /// Actions applied when a dynamic search rule matches.
    /// </summary>
    public class DSRActions
    {
        /// <summary>
        /// Documents to pin to a fixed result position.
        /// </summary>
        [JsonPropertyName("pin")]
        public IEnumerable<DSRPin> Pin { get; set; }

        /// <summary>
        /// Documents whose relevancy score is scaled.
        /// Weight greater than 1 boosts, less than 1 demotes, and 0 hides.
        /// </summary>
        [JsonPropertyName("scale")]
        public IEnumerable<DSRScale> Scale { get; set; }
    }

    /// <summary>
    /// Pins a document to a fixed result position.
    /// </summary>
    public class DSRPin
    {
        /// <summary>
        /// Document id to pin.
        /// </summary>
        [JsonPropertyName("id")]
        public string Id { get; set; }

        /// <summary>
        /// Zero-based position where the document is pinned.
        /// </summary>
        [JsonPropertyName("position")]
        public int Position { get; set; }

        /// <summary>
        /// Index the pin applies to. When null or omitted, the pin applies to any index containing the document id.
        /// </summary>
        [JsonPropertyName("indexUid")]
        public string IndexUid { get; set; }
    }

    /// <summary>
    /// Scales selected documents' relevancy.
    /// </summary>
    public class DSRScale
    {
        /// <summary>
        /// Multiplicative weight applied to the selected documents' relevancy score.
        /// </summary>
        [JsonPropertyName("weight")]
        public double Weight { get; set; }

        /// <summary>
        /// Document ids to scale.
        /// </summary>
        [JsonPropertyName("ids")]
        public IEnumerable<string> Ids { get; set; }

        /// <summary>
        /// Filter selecting documents to scale. A string or a nested filter array, same shape as search filters.
        /// </summary>
        [JsonPropertyName("filter")]
        public dynamic Filter { get; set; }

        /// <summary>
        /// Index the scale applies to. When null or omitted, the scale applies to any index.
        /// </summary>
        [JsonPropertyName("indexUid")]
        public string IndexUid { get; set; }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http.Json;
using System.Threading;
using System.Threading.Tasks;

using Meilisearch.Extensions;

namespace Meilisearch
{
    public partial class Index
    {
        /// <summary>
        /// Gets the proximity precision setting.
        /// </summary>
        /// <param name="cancellationToken">The cancellation token for this call.</param>
        /// <returns>Returns the proximity precision setting.</returns>
        public async Task<string> GetProximityPrecisionAsync(CancellationToken cancellationToken = default)
        {
            return await _http.GetFromJsonAsync<string>($"indexes/{Uid}/settings/proximity-precision", cancellationToken: cancellationToken)
                .ConfigureAwait(false);
        }

        /// <summary>
        /// Updates the proximity precision setting.
        /// </summary>
        /// <param name="proximityPrecision">The new proximity precision setting.</param>
        /// <param name="cancellationToken">The cancellation token for this call.</param>
        /// <returns>Returns the task info of the asynchronous task.</returns>
        public async Task<TaskInfo> UpdateProximityPrecisionAsync(string proximityPrecision, CancellationToken cancellationToken = default)
        {
            var responseMessage =
                await _http.PutAsJsonAsync($"indexes/{Uid}/settings/proximity-precision", proximityPrecision, cancellationToken: cancellationToken)
                    .ConfigureAwait(false);

            return await responseMessage.Content.ReadFromJsonAsync<TaskInfo>(cancellationToken: cancellationToken)
                .ConfigureAwait(false);
        }

        /// <summary>
        /// Resets proximity precision setting.
        /// </summary>
        /// <param name="cancellationToken">The cancellation token for this call.</param>
        /// <returns>Returns the task info of the asynchronous task.</returns>
        public async Task<TaskInfo> ResetProximityPrecisionAsync(CancellationToken cancellationToken = default)
        {
            var response = await _http.DeleteAsync($"indexes/{Uid}/settings/proximity-precision", cancellationToken)
                .ConfigureAwait(false);

            return await response.Content.ReadFromJsonAsync<TaskInfo>(cancellationToken: cancellationToken).ConfigureAwait(false);
        }
    }
}

